async function downloadCreatorActa(type){
  const id=creatorRoomId,code=creatorCodeMap()[id]||'';
  if(!id||!code)return toast('No se encontró el código de creador.');
  try{
    const response=await fetch('/api/community/creator-acta',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({publicId:id,creatorCode:code,type})});
    if(!response.ok){const data=await response.json().catch(()=>({}));throw new Error(data.error||'No se pudo descargar el acta.');}
    const blob=await response.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');
    const disposition=response.headers.get('content-disposition')||'',match=disposition.match(/filename="?([^";]+)"?/i);
    a.href=url;a.download=match?.[1]||`LA_GORDA_Campeonato_ACTA.${type}`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);
  }catch(e){toast(e.message)}
}
