async function refreshCreatorRoomView(silent=true){if(!creatorRoomId)return;const id=creatorRoomId,code=creatorCodeMap()[id]||'';if(!code){closeCreatorRoom();await recoverCreatorById(id,false);return}try{if(!silent){$('creatorRoomBody').className='creatorRoomLoading';$('creatorRoomBody').textContent='Actualizando…'}$('creatorRoomError').textContent='';const data=await api('/api/community/creator-state',{method:'POST',body:JSON.stringify({publicId:creatorRoomId,creatorCode:code})});renderCreatorRoom(data)}catch(e){if(!silent)$('creatorRoomError').textContent=e.message}}
