async function submitRoomAccess(){if(!roomAccessTarget)return;const key=String($('roomAccessKey')?.value||'').trim();if(!key){$('roomAccessError').textContent='Escribí la clave de la sala.';return}const btn=$('roomAccessSubmit');try{btn.disabled=true;$('roomAccessError').textContent='';const result=await api('/api/community/room-access',{method:'POST',body:JSON.stringify({publicId:roomAccessTarget.id,accessKey:key})}),url=roomAccessTarget.action==='watch'?result.transmissionUrl:result.joinUrl;if(!url)throw new Error(roomAccessTarget.action==='watch'?'La transmisión todavía no está disponible.':'La sala todavía no permite entrar.');location.href=url}catch(e){$('roomAccessError').textContent=e.message}finally{btn.disabled=false}}

function renderState(){renderIdentity();renderMessages();renderLive();renderWhatsapp();renderCommunityBanners();renderPrivateRoomAvailability();renderPublicRooms();$('onlineText').textContent='EN LÍNEA';for(const id of ['chatInput','drawerInput','sendBtn','drawerSendBtn','emojiBtn','stickerBtn','drawerEmojiBtn','drawerStickerBtn']){if($(id))$(id).disabled=state.chatEnabled===false}if($('chatInput'))$('chatInput').placeholder=state.chatEnabled===false?'Chat pausado por La Gorda':'Escribí un mensaje…';$('drawerInput').placeholder=state.chatEnabled===false?'Chat pausado por La Gorda':'Escribí un mensaje…';if(state.chatEnabled===false){closePicker('desktop');closePicker('drawer')}renderLeaderboard()}
function hasExplicitRoomDestination(){const qs=new URLSearchParams(location.search);return Boolean(qs.get('mesa')||qs.get('ver')||qs.get('quedar')==='1')}
async function resumeActiveGame(){if(hasExplicitRoomDestination())return false;try{const d=await api('/api/community/resume');if(d?.resume&&d.url){document.body?.setAttribute('aria-busy','true');location.replace(d.url);return true}}catch{}return false}
async function refresh(silent=true){if(await resumeActiveGame())return;try{state=await api(`/api/community/state?visitorId=${encodeURIComponent(visitorId)}`);renderState()}catch(e){if(!silent)toast(e.message)}}
async function reportMessage(messageId){if(!messageId)return;if(!confirm('¿Seguro que querés reportar este mensaje?'))return;try{const d=await api('/api/community/report',{method:'POST',body:JSON.stringify({visitorId,messageId})});if(d.state)state=d.state;renderState();toast(d.alreadyReported?'Este mensaje ya estaba reportado.':'Reporte enviado para revisión.')}catch(e){toast(e.message)}}
async function sendFrom(input){const text=input.value.trim();if(!text)return;if(!(await ensureName()))return;try{input.disabled=true;const d=await api('/api/community/chat',{method:'POST',body:JSON.stringify({visitorId,name,text})});input.value='';if(d.state)state=d.state;closePicker(input.id==='drawerInput'?'drawer':'desktop');renderState()}catch(e){toast(e.message)}finally{input.disabled=state.chatEnabled===false;try{input.focus({preventScroll:true})}catch{input.focus()}}}
function pickerIds(scope){return scope==='drawer'?{host:'drawerPicker',emoji:'drawerEmojiBtn',sticker:'drawerStickerBtn',input:'drawerInput'}:{host:'desktopPicker',emoji:'emojiBtn',sticker:'stickerBtn',input:'chatInput'}}
function closePicker(scope){const ids=pickerIds(scope),host=$(ids.host);pickerMode[scope]='';if(host){host.className='chatPicker';host.innerHTML=''}$(ids.emoji)?.classList.remove('active');$(ids.sticker)?.classList.remove('active')}
function insertEmoji(scope,emoji){const ids=pickerIds(scope),input=$(ids.input),allowed=stickers()?.commonEmojis||[];if(!allowed.includes(emoji)||input.disabled)return;const selected=[...input.value].filter(char=>allowed.includes(char)).length;if(selected>=4){toast('Podés agregar hasta 4 emojis del menú por mensaje.');return}const start=input.selectionStart??input.value.length,end=input.selectionEnd??start;input.value=`${input.value.slice(0,start)}${emoji}${input.value.slice(end)}`.slice(0,Number(state.maxLength)||180);const next=Math.min(input.value.length,start+emoji.length);closePicker(scope);try{input.focus({preventScroll:true});input.setSelectionRange(next,next)}catch{input.focus()}}
function renderPicker(scope,type){const ids=pickerIds(scope),host=$(ids.host),helper=stickers();if(!helper)return;if(pickerMode[scope]===type){closePicker(scope);return}pickerMode[scope]=type;$(ids.emoji).classList.toggle('active',type==='emoji');$(ids.sticker).classList.toggle('active',type==='sticker');if(type==='emoji'){host.className='chatPicker emojis show';host.innerHTML=helper.commonEmojis.map(emoji=>`<button type="button" data-community-emoji="${emoji}">${emoji}</button>`).join('');host.querySelectorAll('[data-community-emoji]').forEach(btn=>btn.onclick=()=>insertEmoji(scope,btn.dataset.communityEmoji));return}host.className='chatPicker stickers show';host.innerHTML=`<div class="chatPickerHint">Los stickers se envían solos con un toque.</div>${helper.stickers.map(item=>`<button class="premiumStickerButton" type="button" data-community-sticker="${esc(item.id)}">${helper.sticker(item.id,{className:'premiumStickerMenuIcon',replay:false})}</button>`).join('')}`;host.querySelectorAll('[data-community-sticker]').forEach(btn=>btn.onclick=()=>sendSticker(scope,btn.dataset.communitySticker))}
async function sendSticker(scope,stickerId){if(state.chatEnabled===false||!stickers()?.get(stickerId))return;if(!(await ensureName()))return;const now=Date.now();while(stickerSendTimes.length&&now-stickerSendTimes[0]>=10000)stickerSendTimes.shift();const last=stickerSendTimes.at(-1)||0;if(now-last<1200||stickerSendTimes.length>=4){toast('Esperá un momento antes de enviar otro sticker.');return}stickerSendTimes.push(now);try{const d=await api('/api/community/chat',{method:'POST',body:JSON.stringify({visitorId,name,stickerId})});if(d.state)state=d.state;closePicker(scope);renderState()}catch(e){stickerSendTimes.pop();toast(e.message)}}
function markChatRead(){const messages=state.messages||[];lastReadMessageId=messages.at(-1)?.id||lastReadMessageId;$('chatUnreadLabel').textContent='ABRIR';$('mobileChatBar').classList.remove('hasUnread')}
function openChat(){ensureName().then(ok=>{if(!ok)return;chatOpen=true;$('chatDrawer').classList.remove('hidden');markChatRead();renderMessages();queueMicrotask(()=>{const host=$('drawerMessages');if(host)host.scrollTop=host.scrollHeight})})}
function closeChat(){closePicker('drawer');chatOpen=false;$('chatDrawer').classList.add('hidden');renderMessages()}
function bindChatDrag(){const panel=$('chatDrawer'),head=panel?.querySelector('.chatHead');if(!panel||!head)return;let startY=0,dragging=false;head.addEventListener('pointerdown',e=>{if(e.target.closest('button,input,a'))return;startY=e.clientY;dragging=true;try{head.setPointerCapture(e.pointerId)}catch{}});head.addEventListener('pointerup',e=>{if(!dragging)return;dragging=false;if(e.clientY-startY>48)closeChat()});head.addEventListener('pointercancel',()=>dragging=false);let touch=null;const protectedTarget=target=>Boolean(target?.closest?.('button,input,textarea,select,a,[contenteditable="true"],.chatPicker,.premiumSticker,.premiumStickerButton'));panel.addEventListener('touchstart',e=>{if(!chatOpen||e.touches.length!==1||e.target.closest('.chatHead')||protectedTarget(e.target))return;const t=e.touches[0],messages=e.target.closest('#drawerMessages');touch={x:t.clientX,y:t.clientY,inMessages:Boolean(messages),scrollTop:messages?messages.scrollTop:0}},{passive:true});panel.addEventListener('touchend',e=>{if(!touch){return}const t=e.changedTouches?.[0],gesture=touch;touch=null;if(!t)return;const dy=t.clientY-gesture.y,dx=t.clientX-gesture.x;if(dy<58||dy<Math.abs(dx)*1.15)return;if(gesture.inMessages&&gesture.scrollTop>4)return;closeChat()},{passive:true});panel.addEventListener('touchcancel',()=>touch=null,{passive:true})}
function randomCard(){const suits=[{symbol:'♥',color:'red',face:'corazon'},{symbol:'♦',color:'red',face:'diamante'},{symbol:'♠',color:'black',face:'pica'},{symbol:'♣',color:'black',face:'trebol'}],suit=suits[Math.floor(Math.random()*suits.length)],value=1+Math.floor(Math.random()*13);return {...suit,value,rank:value===1?'A':value===11?'J':value===12?'Q':value===13?'K':String(value)}}
function showCard(card,hidden=false){const host=$('playingCard');if(hidden||!card){host.className='playingCard back';host.style.backgroundImage='';host.innerHTML='';return}host.className='playingCard';host.style.backgroundImage=`url('/assets/cards/${card.face}.webp')`;host.innerHTML=`<div class="cardIndex top ${card.color}">${esc(card.rank)}<small>${card.symbol}</small></div><div class="cardIndex bottom ${card.color}">${esc(card.rank)}<small>${card.symbol}</small></div>`}
function gameTitle(type){return type==='red_black'?'ROJO O NEGRO':'MAYOR O MENOR'}
function resetMini(){mini.score=0;mini.current=null;mini.ended=false;mini.busy=false;mini.message='';mini.best=Number(bestByType[mini.type])||0}
function setGame(type){if(!['red_black','higher_lower'].includes(type))type='red_black';mini.type=type;safeStorage.set(storage.game,type);resetMini();if(type==='higher_lower')mini.current=randomCard();renderGame()}
function renderGame(){const type=mini.type;document.querySelectorAll('[data-game-tab]').forEach(b=>b.classList.toggle('active',b.dataset.gameTab===type));$('gameTitle').textContent=gameTitle(type);$('gameHint').textContent=type==='red_black'?'Elegí el color de la próxima carta. Cada acierto suma uno a tu racha.':'Mirá la carta actual y elegí si la próxima será mayor o menor. Los empates mantienen la racha.';$('gameScore').textContent=mini.score;$('gameBest').textContent=Math.max(Number(bestByType[type])||0,mini.best||0);if(type==='higher_lower'&&!mini.current&&!mini.ended)mini.current=randomCard();showCard(mini.current,type==='red_black'&&!mini.current);$('gameResult').textContent=mini.message||(type==='red_black'?'Elegí rojo o negro.':`Carta actual: ${mini.current.rank}${mini.current.symbol}. ¿La próxima será mayor o menor?`);$('gameChoices').innerHTML=type==='red_black'?'<button class="redChoice" data-choice="red">ROJO</button><button class="blackChoice" data-choice="black">NEGRO</button>':'<button class="higherChoice" data-choice="higher">MAYOR</button><button class="lowerChoice" data-choice="lower">MENOR</button>';$('gameChoices').classList.toggle('hidden',mini.ended);$('gameRestart').classList.toggle('hidden',!mini.ended);$('gameChoices').querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>playMini(b.dataset.choice));renderLeaderboard()}
function renderLeaderboard(){if(!$('leaderboard'))return;const board=state.leaderboards?.[mini.type]||[];$('leaderboard').innerHTML=`<b>Mejores rachas de la comunidad:</b><br>${board.length?board.slice(0,5).map((x,i)=>`${i+1}. ${esc(x.name)} · ${Number(x.bestScore)||0}`).join(' &nbsp;·&nbsp; '):'Todavía no hay puntajes.'}`}
async function submitScore(score){if(!validName(name)||score<=0)return;try{state=await api('/api/community/score',{method:'POST',body:JSON.stringify({visitorId,name,gameType:mini.type,score})});renderLeaderboard()}catch{}}
async function playMini(choice){if(mini.ended||mini.busy)return;mini.busy=true;const next=randomCard();let correct=false,tie=false;if(mini.type==='red_black')correct=choice===next.color;else{const current=mini.current||randomCard();mini.current=current;tie=next.value===current.value;correct=tie||(choice==='higher'?next.value>current.value:next.value<current.value)}showCard(next);if(tie){mini.current=next;mini.message=`Empate: salió ${next.rank}${next.symbol}. La racha sigue igual.`;mini.busy=false;renderGame();return}if(correct){mini.score++;mini.best=Math.max(mini.best,mini.score);bestByType[mini.type]=Math.max(Number(bestByType[mini.type])||0,mini.best);safeStorage.set(storage.best,JSON.stringify(bestByType));mini.current=next;mini.message=mini.type==='red_black'?`¡Correcto! Salió ${next.rank}${next.symbol}. Elegí otra vez.`:`¡Correcto! Salió ${next.rank}${next.symbol}. ¿Mayor o menor?`;mini.busy=false;renderGame();submitScore(mini.best);return}mini.ended=true;mini.current=next;mini.message=`Te equivocaste: salió ${next.rank}${next.symbol}. Racha final: ${mini.score}.`;mini.busy=false;bestByType[mini.type]=Math.max(Number(bestByType[mini.type])||0,mini.score);safeStorage.set(storage.best,JSON.stringify(bestByType));renderGame();submitScore(mini.score)}
function openGame(type){$('gameOverlay').classList.remove('hidden');setGame(type||mini.type)}
function closeGame(){$('gameOverlay').classList.add('hidden')}
function openWhatsapp(){$('whatsappOverlay').classList.remove('hidden')}
function closeWhatsapp(){$('whatsappOverlay').classList.add('hidden')}
function bind(){$('nameForm').addEventListener('submit',e=>{e.preventDefault();saveName()});$('roomAccessForm')?.addEventListener('submit',e=>{e.preventDefault();submitRoomAccess()});if($('closeRoomAccessBtn'))$('closeRoomAccessBtn').onclick=closeRoomAccess;$('createPrivateRoomTile').onclick=openPrivateRoom;$('privateRoomForm').addEventListener('submit',e=>{e.preventDefault();createPrivateRoom()});$('closePrivateRoomBtn').onclick=closePrivateRoom;$('newPrivateRoomDoneBtn').onclick=closePrivateRoom;$('sharePrivateRoomBtn').onclick=sharePrivateRoom;$('copyPrivateRoomBtn').onclick=copyPrivateRoom;if($('privateRoomPlayBtn'))$('privateRoomPlayBtn').onclick=()=>lastPrivateRoom?.id&&playCreatorRoomById(lastPrivateRoom.id);if($('privateRoomJoinBtn'))$('privateRoomJoinBtn').onclick=()=>lastPrivateRoom?.id&&viewCreatorRoomById(lastPrivateRoom.id);if($('closeCreatorRoomBtn'))$('closeCreatorRoomBtn').onclick=closeCreatorRoom;document.querySelectorAll('[data-private-choice]').forEach(btn=>btn.onclick=()=>{if(!btn.disabled)privateRoomSetChoice(btn.dataset.privateChoice,btn.dataset.value)});for(const id of ['privateRuleAmbo','privateRuleLine75','privateRuleCorners','privateRuleDoubleLine','privateRuleTripleLine'])$(id).onchange=updatePrivateRoomForm;if($('privateOnlyBingo90'))$('privateOnlyBingo90').onclick=()=>{$('privateRuleAmbo').checked=false;privateRoomSetChoice('lines','0')};if($('privateOnlyBingo75'))$('privateOnlyBingo75').onclick=()=>{for(const id of ['privateRuleLine75','privateRuleCorners','privateRuleDoubleLine','privateRuleTripleLine'])$(id).checked=false;updatePrivateRoomForm()};$('publicRoomName').oninput=updatePrivateRoomSummary;$('publicRoomStartsAt').onchange=updatePrivateRoomSummary;if($('privateRoomAccessKey'))$('privateRoomAccessKey').oninput=updatePrivateRoomSummary;$('cancelNameBtn').onclick=()=>closeName(false);$('nameInput').addEventListener('pointerdown',()=>setTimeout(focusNameInput,0));$('identityBtn').onclick=()=>{if(!validName(name))askName()};$('sendBtn').onclick=()=>sendFrom($('chatInput'));$('chatInput').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();sendFrom($('chatInput'))}};$('drawerSendBtn').onclick=()=>sendFrom($('drawerInput'));$('drawerInput').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();sendFrom($('drawerInput'))}};$('emojiBtn').onclick=()=>renderPicker('desktop','emoji');$('stickerBtn').onclick=()=>renderPicker('desktop','sticker');$('drawerEmojiBtn').onclick=()=>renderPicker('drawer','emoji');$('drawerStickerBtn').onclick=()=>renderPicker('drawer','sticker');$('mobileChatBar').onclick=openChat;$('closeChatBtn').onclick=closeChat;$('whatsappTile').onclick=openWhatsapp;$('closeWhatsappBtn').onclick=closeWhatsapp;document.querySelectorAll('[data-open-game]').forEach(el=>el.onclick=()=>openGame(el.dataset.openGame));$('closeGameBtn').onclick=closeGame;document.querySelectorAll('[data-game-tab]').forEach(el=>el.onclick=()=>setGame(el.dataset.gameTab));$('gameRestart').onclick=()=>{resetMini();if(mini.type==='higher_lower')mini.current=randomCard();renderGame()};document.querySelectorAll('[data-nav]').forEach(btn=>btn.onclick=()=>{document.querySelectorAll('[data-nav]').forEach(x=>x.classList.remove('active'));btn.classList.add('active');const n=btn.dataset.nav;if(n==='home')scrollTo({top:0,behavior:'smooth'});if(n==='games')$('gamesSection').scrollIntoView({behavior:'smooth',block:'center'});if(n==='chat')openChat()});document.addEventListener('pointerdown',e=>{for(const scope of ['desktop','drawer']){const ids=pickerIds(scope),host=$(ids.host);if(!pickerMode[scope])continue;if(host.contains(e.target)||$(ids.emoji).contains(e.target)||$(ids.sticker).contains(e.target))continue;closePicker(scope)}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){closePicker('desktop');closePicker('drawer');closeChat();closeGame();closeWhatsapp();closePrivateRoom();closeRoomAccess();closeCreatorRoom();if(!$('nameOverlay').classList.contains('hidden'))closeName(false)}});bindChatDrag()}
async function init(){bind();renderIdentity();if(await resumeActiveGame())return;await refresh(false);pollTimer=setInterval(()=>refresh(true),4000);window.addEventListener('focus',()=>refresh(true));document.addEventListener('visibilitychange',()=>{if(!document.hidden)resumeActiveGame()})}
window.addEventListener('DOMContentLoaded',init);
